// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DpoListAdvisories DPO-07 — advisory questions to the DPO, optionally filtered by department or status
	// (GET /admin/v1/dpo/advisories)
	DpoListAdvisories(ctx context.Context, request DpoListAdvisoriesRequestObject) (DpoListAdvisoriesResponseObject, error)
	// DpoSubmitAdvisory DPO-07 — a department sends a question to the DPO (ม.42(1))
	// (POST /admin/v1/dpo/advisories)
	DpoSubmitAdvisory(ctx context.Context, request DpoSubmitAdvisoryRequestObject) (DpoSubmitAdvisoryResponseObject, error)
	// DpoGetAdvisory DPO-07 — one advisory question
	// (GET /admin/v1/dpo/advisories/{id})
	DpoGetAdvisory(ctx context.Context, request DpoGetAdvisoryRequestObject) (DpoGetAdvisoryResponseObject, error)
	// DpoAnswerAdvisory DPO-07's own acceptance criterion — answer the question and promote it into the searchable knowledge base in the same step (open -> answered)
	// (POST /admin/v1/dpo/advisories/{id}/answer)
	DpoAnswerAdvisory(ctx context.Context, request DpoAnswerAdvisoryRequestObject) (DpoAnswerAdvisoryResponseObject, error)
	// DpoListAppointments The tenant's DPO appointment register (DPO-01, ม.41)
	// (GET /admin/v1/dpo/appointments)
	DpoListAppointments(ctx context.Context, request DpoListAppointmentsRequestObject) (DpoListAppointmentsResponseObject, error)
	// DpoCreateAppointment Register a DPO appointment
	// (POST /admin/v1/dpo/appointments)
	DpoCreateAppointment(ctx context.Context, request DpoCreateAppointmentRequestObject) (DpoCreateAppointmentResponseObject, error)
	// DpoGetAppointment One DPO appointment
	// (GET /admin/v1/dpo/appointments/{id})
	DpoGetAppointment(ctx context.Context, request DpoGetAppointmentRequestObject) (DpoGetAppointmentResponseObject, error)
	// DpoUpdateAppointment Change a DPO appointment — including the appointment order file, the PDPC-notification date and its evidence file, and ending the appointment
	// (PATCH /admin/v1/dpo/appointments/{id})
	DpoUpdateAppointment(ctx context.Context, request DpoUpdateAppointmentRequestObject) (DpoUpdateAppointmentResponseObject, error)
	// DpoListIndependenceDeclarations DPO-03: one appointment's own yearly independence/conflict-of-interest declarations, newest year first
	// (GET /admin/v1/dpo/appointments/{id}/independence-declarations)
	DpoListIndependenceDeclarations(ctx context.Context, request DpoListIndependenceDeclarationsRequestObject) (DpoListIndependenceDeclarationsResponseObject, error)
	// DpoRecordIndependenceDeclaration DPO-03: record or edit the still-unsigned declaration for one year (ม.42) — refused once that year is already signed
	// (POST /admin/v1/dpo/appointments/{id}/independence-declarations)
	DpoRecordIndependenceDeclaration(ctx context.Context, request DpoRecordIndependenceDeclarationRequestObject) (DpoRecordIndependenceDeclarationResponseObject, error)
	// DpoListDeadlines DPO-05: near-deadline and overdue items across every module that already tracks a legal deadline (today: DSAR 30-day SLA, breach 72-hour PDPC notice), on one page
	// (GET /admin/v1/dpo/deadlines)
	DpoListDeadlines(ctx context.Context, request DpoListDeadlinesRequestObject) (DpoListDeadlinesResponseObject, error)
	// DpoSignIndependenceDeclaration DPO-03's own acceptance criterion: sign a year's declaration once, optionally attaching the caller's own clean signed-evidence upload
	// (POST /admin/v1/dpo/independence-declarations/{id}/sign)
	DpoSignIndependenceDeclaration(ctx context.Context, request DpoSignIndependenceDeclarationRequestObject) (DpoSignIndependenceDeclarationResponseObject, error)
	// DpoSearchKbArticles DPO-07 — the searchable knowledge base (every published article, incl. ones promoted from an answered advisory)
	// (GET /admin/v1/dpo/kb-articles)
	DpoSearchKbArticles(ctx context.Context, request DpoSearchKbArticlesRequestObject) (DpoSearchKbArticlesResponseObject, error)
	// DpoListRequirementChecks Every ม.41(2) DPO-requirement screening round for a legal entity, newest first (DPO-02)
	// (GET /admin/v1/dpo/requirement-checks)
	DpoListRequirementChecks(ctx context.Context, request DpoListRequirementChecksRequestObject) (DpoListRequirementChecksResponseObject, error)
	// DpoAssessRequirementCheck Answer the ม.41(2) / 2023 PDPC-notice DPO-appointment checklist for a legal entity (DPO-02)
	// (POST /admin/v1/dpo/requirement-checks)
	DpoAssessRequirementCheck(ctx context.Context, request DpoAssessRequirementCheckRequestObject) (DpoAssessRequirementCheckResponseObject, error)
	// DpoListAssessments The tenant's security-measures checklist runs (DPO-09, ประกาศมาตรการความปลอดภัย พ.ศ. 2565)
	// (GET /admin/v1/dpo/security-assessments)
	DpoListAssessments(ctx context.Context, request DpoListAssessmentsRequestObject) (DpoListAssessmentsResponseObject, error)
	// DpoRecordAssessment Record a run of a published security-measures checklist (DPO-09): every yes_no item answered "no" automatically opens a remediation task
	// (POST /admin/v1/dpo/security-assessments)
	DpoRecordAssessment(ctx context.Context, request DpoRecordAssessmentRequestObject) (DpoRecordAssessmentResponseObject, error)
	// DpoGetAssessment One assessment run, with its remediation tasks
	// (GET /admin/v1/dpo/security-assessments/{id})
	DpoGetAssessment(ctx context.Context, request DpoGetAssessmentRequestObject) (DpoGetAssessmentResponseObject, error)
	// DpoListTasks DPO-06: the kanban/list view of every dpo.tasks job, whatever module opened it (RRA-07/DPO-09/DPA-12/PNG-07/ROPA-19/DPIA-08/RRA-08/RTG-10), filterable by status/source_type/priority/assignee
	// (GET /admin/v1/dpo/tasks)
	DpoListTasks(ctx context.Context, request DpoListTasksRequestObject) (DpoListTasksResponseObject, error)
	// DpoGetTask One dpo.tasks remediation job by id (RRA-07's own tracking view, shared by every source that opens one)
	// (GET /admin/v1/dpo/tasks/{id})
	DpoGetTask(ctx context.Context, request DpoGetTaskRequestObject) (DpoGetTaskResponseObject, error)
	// DpoAssignTask DPO-06: set or change who is assigned, who reviews, the due date and the priority on an already-created task (the module description's own "มีผู้ตรวจ วันครบกำหนด และความสำคัญ") — never a status move
	// (POST /admin/v1/dpo/tasks/{id}/assign)
	DpoAssignTask(ctx context.Context, request DpoAssignTaskRequestObject) (DpoAssignTaskResponseObject, error)
	// DpoUpdateTaskStatus RRA-07: move a task through created -> assigned -> in_review -> done -> closed; closing a "ropa_gap" task re-checks that finding's rule
	// (POST /admin/v1/dpo/tasks/{id}/status)
	DpoUpdateTaskStatus(ctx context.Context, request DpoUpdateTaskStatusRequestObject) (DpoUpdateTaskStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

